import{z as l,x as A,o as E,c as d,q as B,j as i,D as t,d as e,s,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"卡诺图与化简","description":"","frontmatter":{"title":"卡诺图与化简","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/karnaugh-map.md","filePath":"cs/karnaugh-map.md","lastUpdated":1791413859000}'),p={name:"cs/karnaugh-map.md"};function h(C,a,m,c,u,f){const n=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=B('<h1 id="卡诺图与化简" tabindex="-1">卡诺图与化简 <a class="header-anchor" href="#卡诺图与化简" aria-label="Permalink to &quot;卡诺图与化简&quot;">​</a></h1><div class="epigraph"><p>相邻的最小项只差一个变量，圈在一起就能消掉那个变量；图把相邻画成格子的邻居。</p><footer>—— 据 Karnaugh, The Map Method for Synthesis of Combinational Logic Circuits, 1953；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/minterm-maxterm">最小项与最大项</a>钉死了规范 SOP/POS。本课不重列 \\(2^n\\) 个最小项，也不从「逻辑综合史」另起。缺口是：规范式通常太长。电路要的是更少的门、更短的式，同时<strong>保持 1-集合不变</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 稍大，规范或项数就是真值表里 1 的个数，没法直接铺门。代数反复用吸收律可以化简，但没有视觉上的「哪些项能合并」。缺口因此不是新的函数类，而是一种排列：把最小项放进格雷码网格，使得几何相邻 \\(\\Leftrightarrow\\) 汉明距离 1，于是 \\(2^k\\) 个相邻 1 合成一个消去 \\(k\\) 个变量的乘积项。</p><p><span class="marginnote">术语翻译：格雷码就是「相邻两个编码只差一位」的排法（00, 01, 11, 10）。卡诺图靠它把「汉明距离为 1」翻译成「格子挨着」，这是整张图唯一的前提。</span></p><p>卡诺图对 \\(n\\le 4\\) 好用，\\(n=5,6\\) 要对折。更大规模交给列表法：<a href="/cs/quine-mccluskey">下一课</a>按重量合并差一位的项，最短式再做集合覆盖。无关项与险象在后面的<a href="/cs/dont-care-hazard">不完全指定与险象</a>一课展开。</p><h3 id="圈不是「把所有-1-圈进一个最大圈」" tabindex="-1">圈不是「把所有 1 圈进一个最大圈」 <a class="header-anchor" href="#圈不是「把所有-1-圈进一个最大圈」" aria-label="Permalink to &quot;圈不是「把所有 1 圈进一个最大圈」&quot;">​</a></h3><p>每个 1 必须被至少一个质蕴涵项覆盖；圈要乘 2 的幂、不能斜切。贪心画一个最大圈可能迫使别处补很多小圈。本课只要求：合法圈对应乘积项，覆盖完整。最优覆盖是集合覆盖，图上靠眼力，不是多项式算法。</p><p><span class="marginnote">常见误区：初学者容易以为「每个圈都要尽量大、圈与圈不能重叠」。实际上圈允许重叠、允许小到 1 格；真正的大敌是为了凑一个最大圈，害得角落里的 1 落单、被迫多补小圈。</span></p><p><span class="marginnote">Karnaugh 1953 把 Veitch 图改成格雷码相邻。Harris 用它当手算综合的主工具。本栏后课的 ALU 控制逻辑，默认已经会从真值表收成几项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 \\(2^n\\) 格，行、列按格雷码标变量。填 1/0。圈 \\(1,2,4,8,\\ldots\\) 个相邻 1（含卷绕相邻）。每个圈读出不变的变量得乘积项，所有圈的或即化简 SOP。对偶可圈 0 得 POS。</p>',13)),(E(),i(o,null,{default:t(()=>[s(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOP%5B%22%E8%A7%84%E8%8C%83%E6%9C%80%E5%B0%8F%E9%A1%B9%E4%B9%8B%E5%92%8C%22%5D%20--%3E%20MAP%5B%22%E6%A0%BC%E9%9B%B7%E7%A0%81%E7%BD%91%E6%A0%BC%22%5D%0A%20%20MAP%20--%3E%20GROUP%5B%222%5Ek%20%E7%9B%B8%E9%82%BB%E5%9C%88%22%5D%0A%20%20GROUP%20--%3E%20MIN%5B%22%E8%BE%83%E5%B0%91%E4%B9%98%E7%A7%AF%E9%A1%B9%22%5D%0A%20%20MIN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%97%A0%E5%85%B3%E9%A1%B9%E4%B8%8E%E9%99%A9%E8%B1%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("合并的本质是"),r("a",{href:"/cs/error-correcting-intuition"},"纠错码直觉"),e("里的距离：差一位的两个最小项，那个变量成为无关，式子变短。功能集合不变，延迟和面积通常下降——「通常」是因为多级因式分解还能再短，卡诺图只管两级 SOP。后课门时延会说明：两级与或的深度固定，项再少，关键路径仍可能被扇出拖住。")],-1)),a[5]||(a[5]=r("p",null,[r("span",{class:"marginnote"},"直觉类比：圈 2 的幂个格子像投票消变量——圈里某变量既有 0 票又有 1 票，说明结果与它无关，直接划掉；剩下的变量全体一致，才写进乘积项。")],-1)),(E(),i(o,null,{default:t(()=>[s(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20M0%5B%22m0%20%3D%20A%E2%80%B2%C2%B7B%E2%80%B2%C2%B7C%E2%80%B2%22%5D%20---%7C%22%E5%8F%AA%E5%B7%AE%20B%22%7C%20M2%5B%22m2%20%3D%20A%E2%80%B2%C2%B7B%C2%B7C%E2%80%B2%22%5D%0A%20%20M4%5B%22m4%20%3D%20A%C2%B7B%E2%80%B2%C2%B7C%E2%80%B2%22%5D%20---%7C%22%E5%8F%AA%E5%B7%AE%20B%22%7C%20M6%5B%22m6%20%3D%20A%C2%B7B%C2%B7C%E2%80%B2%22%5D%0A%20%20M0%20---%7C%22%E5%8F%AA%E5%B7%AE%20A%22%7C%20M4%0A%20%20M2%20---%7C%22%E5%8F%AA%E5%B7%AE%20A%22%7C%20M6%0A%20%20M2%20---%20GC%5B%22%E5%9B%9B%E6%A0%BC%E5%9C%88%E6%88%90%E4%B8%80%E4%B8%AA%202x2%20%E5%A4%A7%E5%9C%88%EF%BC%88%E5%90%AB%E5%8D%B7%E7%BB%95%E5%88%97%EF%BC%89%22%5D%0A%20%20M6%20---%20GC%0A%20%20GC%20--%3E%20E%5B%22A%E3%80%81B%20%E9%83%BD%200%2F1%20%E5%90%84%E5%8D%8A%EF%BC%9A%E4%B8%80%E5%B9%B6%E6%B6%88%E5%8E%BB%22%5D%0A%20%20E%20--%3E%20R%5B%22%E6%95%B4%E4%B8%AA%E5%87%BD%E6%95%B0%E5%8C%96%E6%88%90%E5%8D%95%E9%A1%B9%20C%E2%80%B2%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p>同一函数的 SOP 与 POS 哪个更短，看 1 多还是 0 多。本课两种都合法。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课默认函数完全指定、输入同时到达。竞争与静态险象、以及 \\(X\\) 无关项，后面的<a href="/cs/dont-care-hazard">不完全指定与险象</a>一课才加。也不把 HDL 综合器的算法写成步骤。</p><p>后课默认：手算组合逻辑从真值表进卡诺图得到两级式；不完全指定与毛刺另处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>卡诺图把汉明距离 1 画成格子相邻，合并即消去变量。</li><li>圈须为 2 的幂并覆盖全部 1；最短覆盖仍可能要试。</li><li>只管两级 SOP/POS；多级分解与时序不在本课。</li><li>出处：Karnaugh, 1953；Harris and Harris。</li></ul>',6))])}const g=l(p,[["render",h]]);export{P as __pageData,g as default};
